(xLength, yLength) = list(map(int, input().split(' ')))
xValues = list(input().split(' '))
yValues = list(input().split(' '))
table = []
for x in range(xLength):
	col = []
	for y in range(yLength):
		col.append(0)
	table.append(col)
for y in range(yLength):
	for x in range(xLength):
		if xValues[x] == yValues[y]:
			if x == 0 or y == 0:
				table[x][y] = 1
			else:
				table[x][y] = table[x - 1][y - 1] + 1
		elif x == 0 and y == 0:
			table[x][y] = 0
		elif x == 0:
			table[x][y] = table[x][y - 1]
		elif y == 0:
			table[x][y] = table[x - 1][y]
		else:
			table[x][y] = max(table[x][y - 1], table[x - 1][y])
foundLCS = False
x = xLength - 1
y = yLength - 1
LCS = []
while not foundLCS:
	t = table[x][y]
	if x == 0 and y == 0:
		LCS.append(xValues[x])
		foundLCS = True
	elif x == 0:
		if table[x][y - 1] == t:
			y -= 1
		else:
			LCS.append(xValues[x])
			foundLCS = True
	elif y == 0:
		if table[x - 1][y] == t:
			x -= 1
		else:
			LCS.append(xValues[x])
			foundLCS = True
	elif table[x - 1][y] == t:
		x -= 1
	elif table[x][y - 1] == t:
		y -= 1
	else:
		LCS.append(xValues[x])
		t = table[x - 1][y - 1]
		x -= 1
		y -= 1
		if t == 0:
			foundLCS = True
LCS.reverse()
print(' '.join(LCS))
